// Some portions generated by Claude
// Synthetic exploration graphs with distinct shapes (what the canvas draws with Values off: resources and their
// links, types filled in). Deterministic; no private data.
const EX = 'http://example.org/';
function seeded(seed) {
  let s = seed >>> 0;
  return () => { s = (Math.imul(s, 1664525) + 1013904223) >>> 0; return s / 4294967296; };
}
function builder() {
  const nodes = [], edges = [], seen = new Set();
  const node = (name, type) => { const id = EX + name; if (!seen.has(id)) { seen.add(id); nodes.push({ id, label: name, kind: 'iri', ...(type ? { types: [{ id: EX + type, label: type }] } : {}) }); } return id; };
  const link = (source, predicate, target) => edges.push({ id: `${source}|${predicate}|${target}`, source: EX + source, target: EX + target, predicate: EX + predicate, label: predicate });
  return { node, link, graph: () => ({ nodes, edges, revision: 1 }) };
}

const RDF_TYPE = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type';

/**
 * A country with 5 regions, 4 cities each, 3 districts each: a tree three levels deep (86 nodes). With `values`
 * every resource also gets a label literal and a type link to its class node, as the canvas shows with Values on.
 */
export function geoTree(regions = 5, cities = 4, districts = 3, { values = false } = {}) {
  const b = builder();
  const typed = (name, type) => {
    b.node(name, type);
    if (!values) return;
    b.node(type, undefined);
    b.graph().edges.push({ id: `${name}|type|${type}`, source: EX + name, target: EX + type, predicate: RDF_TYPE, label: 'type' });
    const literal = `__rdf_literal__:${JSON.stringify({ type: 'literal', value: name, datatype: '', language: '' })}`;
    b.graph().nodes.push({ id: literal, label: name, kind: 'literal' });
    b.graph().edges.push({ id: `${name}|label`, source: EX + name, target: literal, predicate: 'http://www.w3.org/2000/01/rdf-schema#label', label: 'label' });
  };
  typed('Norway', 'Country');
  for (let r = 0; r < regions; r++) {
    typed(`Region ${r + 1}`, 'Region'); b.link(`Region ${r + 1}`, 'partOf', 'Norway');
    for (let c = 0; c < cities; c++) {
      const city = `City ${r + 1}-${c + 1}`; typed(city, 'City'); b.link(city, 'partOf', `Region ${r + 1}`);
      for (let d = 0; d < districts; d++) { const district = `District ${r + 1}-${c + 1}-${d + 1}`; typed(district, 'District'); b.link(district, 'partOf', city); }
    }
  }
  return b.graph();
}

/** One conference with 40 papers by 25 authors from 6 universities (72 nodes): a dominant hub whose neighbours are not leaves. */
export function conferenceHub(papers = 40, authors = 25, universities = 6) {
  const random = seeded(11), b = builder();
  b.node('Conference', 'Conference');
  for (let u = 0; u < universities; u++) b.node(`University ${u + 1}`, 'University');
  for (let a = 0; a < authors; a++) { b.node(`Author ${a + 1}`, 'Person'); b.link(`Author ${a + 1}`, 'affiliation', `University ${(a % universities) + 1}`); }
  for (let p = 0; p < papers; p++) {
    b.node(`Paper ${p + 1}`, 'Paper'); b.link(`Paper ${p + 1}`, 'presentedAt', 'Conference');
    const count = [1, 2, 2, 3][Math.floor(random() * 4)], chosen = new Set();
    while (chosen.size < count) chosen.add(Math.floor(random() * authors));
    for (const a of chosen) b.link(`Paper ${p + 1}`, 'author', `Author ${a + 1}`);
  }
  return b.graph();
}

/** 30 students in 8 courses, 3 or 4 each (38 nodes): a dense bipartite graph without leaves. */
export function studentCourses(students = 30, courses = 8) {
  const random = seeded(5), b = builder();
  for (let c = 0; c < courses; c++) b.node(`Course ${c + 1}`, 'Course');
  for (let s = 0; s < students; s++) {
    b.node(`Student ${s + 1}`, 'Student');
    const count = random() < .5 ? 3 : 4, chosen = new Set();
    while (chosen.size < count) chosen.add(Math.floor(random() * courses));
    for (const c of chosen) b.link(`Student ${s + 1}`, 'enrolledIn', `Course ${c + 1}`);
  }
  return b.graph();
}

/** 4 manufacturers with 5 to 8 products each in 5 shared categories from 3 suppliers (38 nodes): a tripartite graph. */
export function productCatalog() {
  const random = seeded(3), b = builder();
  const categories = ['Tools', 'Toys', 'Kitchen', 'Garden', 'Office'];
  categories.forEach((c) => b.node(c, 'Category'));
  for (let s = 0; s < 3; s++) b.node(`Supplier ${s + 1}`, 'Supplier');
  let n = 0;
  for (let m = 0; m < 4; m++) {
    b.node(`Maker ${m + 1}`, 'Manufacturer');
    for (let k = 0; k < 5 + m; k++) {
      n++; const product = `Product ${n}`; b.node(product, 'Product');
      b.link(product, 'madeBy', `Maker ${m + 1}`); b.link(product, 'category', categories[Math.floor(random() * categories.length)]); b.link(product, 'suppliedBy', `Supplier ${Math.floor(random() * 3) + 1}`);
    }
  }
  return b.graph();
}

/** 3 clubs of 10 people, dense inside, sparse across, each person with a mailbox resource (65 nodes). */
export function socialCommunities() {
  const random = seeded(7), b = builder();
  for (let c = 0; c < 3; c++) { b.node(`Club ${c + 1}`, 'Club'); b.link(`Club ${c + 1}`, 'city', c === 1 ? 'Bergen' : 'Oslo'); }
  b.node('Oslo', 'City'); b.node('Bergen', 'City');
  for (let i = 0; i < 30; i++) {
    const c = Math.floor(i / 10); b.node(`Person ${i + 1}`, 'Person'); b.link(`Person ${i + 1}`, 'memberOf', `Club ${c + 1}`);
    b.node(`mailbox ${i + 1}`); b.link(`Person ${i + 1}`, 'mbox', `mailbox ${i + 1}`);
    for (let j = i + 1; j < (c + 1) * 10; j++) if (random() < .45) b.link(`Person ${i + 1}`, 'knows', `Person ${j + 1}`);
  }
  for (let k = 0; k < 4; k++) b.link(`Person ${Math.floor(random() * 30) + 1}`, 'knows', `Person ${Math.floor(random() * 30) + 1}`);
  return b.graph();
}
